void Loader_WeaponDef::LoadPtr_WeaponDef(const bool atStreamStart)
{
    assert(varWeaponDefPtr != nullptr);
    
    assert(!atStreamStart);
    
    m_stream.PushBlock(XFILE_BLOCK_TEMP);
    
    if (*varWeaponDefPtr != nullptr)
    {
        const auto zonePtrType = GetZonePointerType(*varWeaponDefPtr);
        if (zonePtrType == ZonePointerType::FOLLOWING || zonePtrType == ZonePointerType::INSERT)
        {
            *varWeaponDefPtr = m_stream.AllocOutOfBlock<WeaponDef>(4);
            
            uintptr_t toInsertLookupEntry = 0;
            if (zonePtrType == ZonePointerType::INSERT)
                toInsertLookupEntry = m_stream.InsertPointerAliasLookup();
            
            varWeaponDef = *varWeaponDefPtr;
            Load_WeaponDef(true);
            
            LoadAsset_WeaponDef(varWeaponDefPtr);
            
            if (zonePtrType == ZonePointerType::INSERT)
                m_stream.SetInsertedPointerAliasLookup(toInsertLookupEntry, *varWeaponDefPtr);
        }
        else
        {
            *varWeaponDefPtr = m_stream.ConvertOffsetToAliasLookup(*varWeaponDefPtr);
        }
    }
    
    m_stream.PopBlock();
}

void Loader_WeaponDef::LoadAsset_WeaponDef(WeaponDef** pAsset)
{
    assert(pAsset != nullptr);
    
    AssetInfoCollector assetInfo(m_zone);
    AssetMarker<AssetWeapon> marker(assetInfo);
    marker.Mark(*pAsset);
    
    auto* reallocatedAsset = m_zone.Memory().Alloc<WeaponDef>();
    std::memcpy(reallocatedAsset, *pAsset, sizeof(WeaponDef));
    
    m_asset_info = reinterpret_cast<XAssetInfo<WeaponDef>*>(LinkAsset(AssetName<AssetWeapon>(**pAsset), reallocatedAsset, assetInfo.GetDependencies(), assetInfo.GetUsedScriptStrings(), assetInfo.GetIndirectAssetReferences()));
    *pAsset = m_asset_info->Asset();
}
